+export const decodeSession = (encoded: string): string | null => {
+  const [compressed, signature] = encoded.split(".");
+  if (!compressed || !signature) return null;
+
+  const hmac = crypto.createHmac("sha256", SECRET);
+  hmac.update(compressed);
+  const expectedSignature = hmac.digest("hex");
+
+  if (signature !== expectedSignature) return null;
+
+  try {
+    const json = Buffer.from(compressed, "base64").toString("utf-8");
+    const data: SessionData = JSON.parse(json);
+
